export interface FreeResult {
  schemaVersion: number;
  serviceKey: FreeServiceKey;
  score: number;
  grade: FreeGrade;
  summary: string;
  findings: FreeFinding[];
  checkedAt: string;
  meta?: FreeResultMeta;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isSeverity(value: unknown): value is FreeSeverity {
  return value === 'high' || value === 'medium' || value === 'low' || value === 'info';
}

function isServiceKey(value: unknown): value is FreeServiceKey {
  return typeof value === 'string' && FREE_SERVICE_KEYS.includes(value as FreeServiceKey);
}

function safeString(value: unknown, fallback = ''): string {
  return typeof value === 'string' ? value : fallback;
}

/** Validate stored JSON without trusting its shape or version. */
export function parseStoredFreeResult(
  value: unknown,
  fallbackServiceKey?: FreeServiceKey,
): FreeResult | null {
  if (!isRecord(value)) return null;
  const serviceKey = isServiceKey(value.serviceKey) ? value.serviceKey : fallbackServiceKey;
  if (!serviceKey) return null;
  const rawFindings = Array.isArray(value.findings) ? value.findings : [];
  const findings: FreeFinding[] = [];
  for (const item of rawFindings) {
    if (!isRecord(item) || !isSeverity(item.severity)) continue;
    const id = safeString(item.id);
    const title = safeString(item.title);
    if (!id || !title) continue;
    findings.push({
      id,
      severity: item.severity,
      title,
      meaning: safeString(item.meaning),
      consequence: safeString(item.consequence),
      recommendation: safeString(item.recommendation),
      serviceKey: safeString(item.serviceKey, 'website_check'),
      ...(typeof item.detail === 'string' ? { detail: item.detail } : {}),
    });
  }
  const rawScore =
    typeof value.score === 'number' && Number.isFinite(value.score) ? value.score : 0;
  const score = Math.min(100, Math.max(0, Math.round(rawScore)));
  const grade =
    value.grade === 'A' ||
    value.grade === 'B' ||
    value.grade === 'C' ||
    value.grade === 'D' ||
    value.grade === 'F'
      ? value.grade
      : gradeForScore(score);
  const meta = isRecord(value.meta) ? (value.meta as FreeResultMeta) : undefined;
  return {
    schemaVersion:
      typeof value.schemaVersion === 'number' && Number.isInteger(value.schemaVersion)
        ? value.schemaVersion
        : 1,
    serviceKey,
    score,
    grade,
    summary: safeString(value.summary, resultSummary(score, findings)),
    findings,
    checkedAt: safeString(value.checkedAt, new Date(0).toISOString()),
    ...(meta ? { meta } : {}),
  };
}

