export function gradeForScore(score: number): FreeGrade {
  if (score >= 90) return 'A';
  if (score >= 80) return 'B';
  if (score >= 70) return 'C';
  if (score >= 60) return 'D';
  return 'F';
}

export function severityLabel(severity: FreeSeverity): string {
  return severity === 'info' ? 'Information' : severity.charAt(0).toUpperCase() + severity.slice(1);
}

export function findingPenalty(severity: FreeSeverity): number {
  if (severity === 'high') return 22;
  if (severity === 'medium') return 10;
  if (severity === 'low') return 4;
  return 0;
}

export function resultSummary(score: number, findings: FreeFinding[]): string {
  const high = findings.filter((f) => f.severity === 'high').length;
  const medium = findings.filter((f) => f.severity === 'medium').length;
  if (high > 0) {
    return `${high} high-priority issue${high === 1 ? '' : 's'} found. Fix these before they become an incident.`;
  }
  if (medium > 0) {
    return `${medium} medium-priority improvement${medium === 1 ? '' : 's'} found. These are worth scheduling soon.`;
  }
  if (score >= 90)
    return 'Strong basics. Keep them current and verify the details that cannot be seen from outside.';
  return 'No major issues were visible from this passive check. There is still room to tighten the basics.';
}
